-- Hybrid work: from Monday, November 9 (game day 36, three weeks after the missions) Seaside Labs is in the office
-- Tuesday to Thursday, and Mondays and Fridays are worked from home. Linda sends the policy on October 26 (two weeks
-- ahead), Maya texts, the all-hands day ends with a reminder, and Sam sends a checklist for working from home. On a
-- remote day you log in at your desk at home (heroes.home_desk) by late_after instead of walking into the office:
-- logging in late is late, never logging in is a missed day, logging off (or walking out of home) before early_before
-- and not coming back is leaving early. The team (config remote_people) stays home; Tom and Sam are at the office every
-- day. The standup is a video call from home with its own conversations (routines.remote_episodes, three for each
-- hero), and sprint planning and the retro move to office days (routines.hybrid_days: Tuesday, Thursday); some of their
-- lines named Monday or Friday, so they are made day-neutral here. Maya's review on Monday, January 4 stays in person.
-- The ALTER TABLE lines are run on DoltHub once; to push this file again, leave them out.
ALTER TABLE routines ADD COLUMN hybrid_days varchar(40);
ALTER TABLE routines ADD COLUMN remote_episodes varchar(1000);


UPDATE routines SET hybrid_days = 'tue' WHERE id = 'planning';
UPDATE routines SET hybrid_days = 'thu' WHERE id = 'retro';
UPDATE routines SET remote_episodes = 'rt_video_jun_1,rt_video_jun_2,rt_video_jun_3,rt_video_dk_1,rt_video_dk_2,rt_video_dk_3,rt_video_pr_1,rt_video_pr_2,rt_video_pr_3' WHERE id = 'standup';

UPDATE turns SET situation = 'Sprint planning. Priya shares the board on the big screen. First story: store managers want to export the weekly sales table as a CSV file. You built that table last sprint, so the work is small: one button and a download.', situation_ko = '스프린트 계획 회의입니다. 프리야가 큰 화면에 보드를 띄웁니다. 첫 스토리는 매장 매니저들이 주간 매출 표를 CSV 파일로 내려받고 싶어 한다는 것입니다. 그 표는 지난 스프린트에 당신이 만들었으니 일은 작습니다. 버튼 하나와 다운로드뿐이에요.' WHERE episode = 'rt_planning_dev_1' AND seq = 1;
UPDATE turns SET situation = 'Sprint planning. The team is in the meeting room, and the board is on the screen. Summit Retail''s store managers keep saying the same thing: the dashboard is slow to load in the mornings. Every other request can wait.', situation_ko = '스프린트 계획 회의입니다. 팀이 회의실에 모였고 화면에 보드가 떠 있습니다. 서밋 리테일 매장 매니저들은 같은 말을 계속합니다. 아침마다 대시보드가 느리게 뜬다고요. 다른 요청은 다 기다릴 수 있습니다.' WHERE episode = 'rt_planning_pr_1' AND seq = 1;
UPDATE turns SET situation = 'Sprint retro. Maya has drawn three columns on the whiteboard: Went well, To improve, Action items. This sprint''s release went out with zero bugs, thanks to a new release checklist the team tried.', situation_ko = '스프린트 회고입니다. 마야가 화이트보드에 세 칸을 그렸습니다. 잘된 것, 개선할 것, 실행 항목. 이번 스프린트 배포는 팀이 새로 써 본 배포 체크리스트 덕분에 버그 없이 나갔습니다.' WHERE episode = 'rt_retro_1' AND seq = 1;
UPDATE turns SET situation = 'Sprint retro. Maya always opens with shout-outs. This sprint, Sam from IT stayed late on Tuesday to fix the build server, so the team could release on time. Sam has joined the retro today.', situation_ko = '스프린트 회고입니다. 마야는 늘 감사 인사로 시작합니다. 이번 스프린트에 IT의 샘이 화요일에 늦게까지 남아 빌드 서버를 고쳐서, 팀이 제때 배포할 수 있었습니다. 오늘은 샘도 회고에 왔습니다.' WHERE episode = 'rt_retro_2' AND seq = 1;
UPDATE turns SET reply_line = 'Thanks. That''s everything. Good sprint, everyone.', reply_ko = '고마워요. 이걸로 끝이에요. 다들 수고했어요.' WHERE episode = 'rt_retro_2' AND seq = 3;
UPDATE episodes SET summary = 'Every other week, Priya plans the next two weeks with the team. Estimate a story, speak up when the sprint gets too full, and flag a risk before you commit.', summary_ko = '2주마다 프리야가 팀과 다음 2주를 계획합니다. 스토리를 추정하고, 스프린트가 너무 차면 말하고, 약속하기 전에 위험 요소를 알리세요.' WHERE id = 'rt_planning_dev_1';
UPDATE episodes SET summary = 'Every other week, Maya runs the sprint retro. Name what went well, raise a problem without blaming anyone, and turn it into an action item you own.', summary_ko = '2주마다 마야가 스프린트 회고를 진행합니다. 잘된 것을 말하고, 누구도 탓하지 않고 문제를 꺼내고, 그것을 당신이 맡는 실행 항목으로 바꾸세요.' WHERE id = 'rt_retro_1';

